import { createAsyncThunk, createSlice } from "@reduxjs/toolkit";
import axios from "axios";

const initialState = {
  company: null,
  isLoading: false,
  isSuccess: false,
  isError: false,
  message: "",
};

// ✅ Register Company
export const registerCompany = createAsyncThunk(
  "company/registerCompany",
  async (companyData, thunkAPI) => {
    try {
      const response = await axios.post(
        "http://localhost:3001/registerCompany",
        {
          companyName: companyData.companyName,
          email: companyData.email,
          password: companyData.password,
          industry: companyData.industry,
          location: companyData.location,
          foundedDate: companyData.foundedDate,
        }
      );
      return response.data.company;
    } catch (error) {
      return thunkAPI.rejectWithValue(
        error.response?.data?.error || "Failed to register company"
      );
    }
  }
);

// ✅ Login Company
export const loginCompany = createAsyncThunk(
  "company/loginCompany",
  async (loginData, thunkAPI) => {
    try {
      const response = await axios.post("http://localhost:3001/login", {
        email: loginData.email,
        password: loginData.password,
        role: "company",
      });
      return response.data.account;
    } catch (error) {
      return thunkAPI.rejectWithValue(
        error.response?.data?.error || "Login failed"
      );
    }
  }
);

const companySlice = createSlice({
  name: "company",
  initialState,
  reducers: {
    logoutCompany: (state) => {
      state.company = null;
      localStorage.removeItem("company");
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(registerCompany.pending, (state) => {
        state.isLoading = true;
      })
      .addCase(registerCompany.fulfilled, (state, action) => {
        state.isLoading = false;
        state.isSuccess = true;
        state.company = action.payload;
        localStorage.setItem("company", JSON.stringify(action.payload));
      })
      .addCase(registerCompany.rejected, (state, action) => {
        state.isLoading = false;
        state.isError = true;
        state.message = action.payload;
      })

      .addCase(loginCompany.pending, (state) => {
        state.isLoading = true;
      })
      .addCase(loginCompany.fulfilled, (state, action) => {
        state.isLoading = false;
        state.isSuccess = true;
        state.company = action.payload;
        localStorage.setItem("company", JSON.stringify(action.payload));
      })
      .addCase(loginCompany.rejected, (state, action) => {
        state.isLoading = false;
        state.isError = true;
        state.message = action.payload;
      });
  },
});

export const { logoutCompany } = companySlice.actions;
export default companySlice.reducer;
